  // start. Keep its real date; fxOn still enforces the seven-day age limit.
  if(!Array.isArray(data)||!data.length||data.length>1500||data.some(r=>r.base!==from||r.quote!==to||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||r.date<earliest||r.date>end||!Number.isFinite(r.rate)||r.rate<=0)||new Set(data.map(r=>r.date)).size!==data.length)throw Error('Invalid FX source');
