  for(const a of Object.values(ch.events?.dividends||{}))corporateActions.push({date:new Date(a.date*1000).toISOString().slice(0,10),kind:'dividend',value:a.amount});
  for(const a of Object.values(ch.events?.splits||{}))corporateActions.push({date:new Date(a.date*1000).toISOString().slice(0,10),kind:'split',value:a.numerator/a.denominator});
  return {rows,corporateActions:corporateActions.filter(a=>a.date>=start&&a.date<=end),sourceUrl,
    currency:ch.meta.currency,exchange:ch.meta.exchangeName,timezone:ch.meta.exchangeTimezoneName};
